{
  "gate_token": "Y7L-VGa2-WVHvtVgZi5Afw",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map is unrolled at the edge of the ruined city.",
      "visual_description": "Wide twilight view of broken spires and toppled banners; in the foreground a parchment map is pinned with a brass compass on a cracked stone.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Mara wakes her tiny clockwork scout.",
      "visual_description": "Close-up of ink-stained fingers turning a key in a small metal fox's tail; blue glass eyes flicker to life under a lantern.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of temptations ahead.",
      "visual_description": "An oil lamp on a stack of maps, a single glowing eye inside its flame casting nervous shadows across Mara's worried face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "A stranger steps from a cracked window pane.",
      "visual_description": "A figure in a clear diving helmet emerges from a tall shattered window, coat reflecting fractured streetlight across wet cobblestones.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They approach the great castle gates.",
      "visual_description": "Two huge iron gates hang crooked between fallруины towers; old royal banners flap in tatters above the small party below.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The lamp refuses the cursed tower's stair.",
      "visual_description": "A spiraling black tower stairway, faintly green at the edges; the oracle lamp's flame leans backward as if recoiling.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Tin fox scouts a frightened market square.",
      "visual_description": "Overturned fruit carts and abandoned shawls in a stone plaza; the clockwork fox creeps low past hiding faces peeking from shutters.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a winged beast in the smoke.",
      "visual_description": "Distant smoke curling over rooftops shaped vaguely like wings; Mara squints through a spyglass, the diver watches the sky.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "An armored patrol clanks down a narrow lane.",
      "visual_description": "Long shadows of polearms and plated boots stretch across alley stones; the tin fox darts behind a broken barrel, eyes dimmed.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "They find an official asleep on his ledger.",
      "visual_description": "A plump man slumped over a heavy book, stamped papers stuck to his sleeves, drool on a wax seal; the lamp glares disapprovingly.",
      "characters": ["sleeping_tax_collector", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Mara charts a path through the magic door.",
      "visual_description": "A tall door carved with rotating sigils glowing faint violet; Mara traces lines on her map that match the door's pattern.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver slips into a mirrored hall.",
      "visual_description": "An immense ballroom of cracked mirrors; the diver wades into a reflection as if it were water, ripples spreading across the glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Behind the mirror, the captive is found.",
      "visual_description": "A small dim cell on the other side of the silvered glass; a bound figure looks up, hopeful, as the diver's helmet pushes through.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The tin fox triggers a distraction across town.",
      "visual_description": "A cascade of clattering bells and falling lanterns down a far stairway; the little metal fox sprints away, key-tail whirring.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The official wakes briefly and stamps the wrong page.",
      "visual_description": "Bleary eyes, a heavy stamp thudding onto a map of the wrong district; Mara grins and pockets the misstamped writ.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The party regroups under torn royal banners.",
      "visual_description": "Beneath shredded flags of a fallen crest, Mara, the diver, the fox, and the lamp huddle around the rescued captive's silhouette.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint for the long stone bridge.",
      "visual_description": "A vast cracked bridge over a misty chasm at dawn; tiny figures run across, coat and banners trailing, lamp swinging wildly.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the map is folded away.",
      "visual_description": "Morning light on green hills beyond the chasm; Mara folds her map, the fox sits proudly, the diver removes the helmet, the lamp sighs in relief.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

